import React, { useEffect, useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

/* ════════════════════════════════════════════════
   TABLEAU DE BORD ÉTUDIANT
════════════════════════════════════════════════ */

function Stars({ n }) {
  const v = parseFloat(n) || 0;
  return (
    <span>
      {[1,2,3,4,5].map(i => (
        <span key={i} style={{ color: i <= Math.round(v) ? '#f59e0b' : 'var(--border)', fontSize: '.85rem' }}>★</span>
      ))}
      <span style={{ fontSize: '.75rem', color: 'var(--text2)', marginLeft: 4 }}>{v.toFixed(1)}</span>
    </span>
  );
}

function SessionCard({ r }) {
  const isToday    = r.session_today;
  const isActive   = r.session_active;
  const isImminent = r.session_imminent;
  const dateStr    = r.date_cours ? new Date(r.date_cours + 'T00:00:00').toLocaleDateString('fr-FR', { weekday: 'short', day: 'numeric', month: 'short' }) : '—';

  let statusColor = '#6c63ff';
  let statusLabel = dateStr;
  let statusIcon  = '📅';
  if (isActive)   { statusColor = '#43e97b'; statusLabel = 'En cours maintenant'; statusIcon = '🟢'; }
  if (isImminent) { statusColor = '#f59e0b'; statusLabel = `Dans ${r.minutes_until} min`; statusIcon = '⏰'; }
  if (isToday && !isActive && !isImminent) { statusColor = '#38bdf8'; statusLabel = `Aujourd'hui ${r.heure_debut?.slice(0,5)}`; statusIcon = '📆'; }

  return (
    <div style={{ padding: '14px 16px', background: 'var(--surface2)', borderRadius: 14, border: `1px solid ${isActive ? 'rgba(67,233,123,0.4)' : isImminent ? 'rgba(245,158,11,0.3)' : 'var(--border)'}`, transition: 'all .2s', boxShadow: isActive ? '0 0 0 3px rgba(67,233,123,0.1)' : 'none' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 8 }}>
        <div>
          <div style={{ fontWeight: 700, fontSize: '.9rem', marginBottom: 3 }}>{r.prof_nom || 'Professeur'}</div>
          <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>🕒 {r.heure_debut?.slice(0,5)} → {r.heure_fin?.slice(0,5)}</div>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div style={{ fontSize: '.72rem', fontWeight: 700, color: statusColor, display: 'flex', alignItems: 'center', gap: 4 }}>
            <span>{statusIcon}</span>{statusLabel}
          </div>
          <div style={{ fontSize: '.7rem', color: 'var(--text2)', marginTop: 3 }}>
            {r.mode_seance === 'en_ligne' ? '🌐 En ligne' : '🏫 Présentiel'}
          </div>
        </div>
      </div>
      {isActive && r.lien_meet && (
        <a href={r.lien_meet} target="_blank" rel="noreferrer" style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '8px 12px', background: 'rgba(67,233,123,0.12)', border: '1px solid rgba(67,233,123,0.3)', borderRadius: 9, textDecoration: 'none', fontSize: '.8rem', color: '#43e97b', fontWeight: 700, marginTop: 8 }}>
          🎥 Rejoindre la session →
        </a>
      )}
    </div>
  );
}

export default function EtudiantDashboard() {
  const { user } = useAuth();
  const navigate  = useNavigate();

  const [reservations, setReservations] = useState([]);
  const [profs, setProfs]               = useState([]);
  const [profil, setProfil]             = useState(null);
  const [loading, setLoading]           = useState(true);

  useEffect(() => {
    Promise.all([
      api.get('/api/reservations/mes-reservations').catch(() => ({ data: [] })),
      api.get('/api/professeurs/').catch(() => ({ data: [] })),
      api.get('/api/etudiants/me').catch(() => ({ data: {} })),
    ]).then(([r, p, pr]) => {
      setReservations(r.data || []);
      setProfs(p.data || []);
      setProfil(pr.data || {});
    }).finally(() => setLoading(false));
  }, []);

  /* ── Stats ── */
  const confirmes  = useMemo(() => reservations.filter(r => r.statut === 'confirmé'), [reservations]);
  const enAttente  = useMemo(() => reservations.filter(r => r.statut === 'en_attente'), [reservations]);
  const prochains  = useMemo(() => confirmes.filter(r => !r.session_past).sort((a,b) => new Date(a.date_cours) - new Date(b.date_cours)), [confirmes]);
  const passes     = useMemo(() => confirmes.filter(r => r.session_past).length, [confirmes]);

  /* ── Profs recommandés (par note, pas encore réservé) ── */
  const profsIds   = useMemo(() => new Set(reservations.map(r => r.prof_id)), [reservations]);
  const recommandes = useMemo(() =>
    profs.filter(p => p.statut_validation === 'validé')
         .sort((a,b) => (parseFloat(b.note_moyenne)||0) - (parseFloat(a.note_moyenne)||0))
         .slice(0, 4)
  , [profs, profsIds]);

  /* ── Profs favoris (les plus réservés) ── */
  const profsResas = useMemo(() => {
    const count = {};
    reservations.forEach(r => { count[r.prof_id] = (count[r.prof_id] || 0) + 1; });
    return Object.entries(count)
      .sort((a,b) => b[1] - a[1])
      .slice(0, 3)
      .map(([id]) => reservations.find(r => r.prof_id === parseInt(id)))
      .filter(Boolean);
  }, [reservations]);

  const nom = profil?.prenom || user?.prenom || 'Étudiant';
  const niveau = profil?.niveau || '';

  if (loading) return (
    <div style={{ padding: 60, textAlign: 'center', color: 'var(--text2)' }}>
      <div style={{ fontSize: '2rem', marginBottom: 12 }}>⏳</div>Chargement...
    </div>
  );

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      {/* ── HEADER SALUTATION ── */}
      <div style={{ marginBottom: 32 }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 16 }}>
          <div>
            <h1 style={{ fontFamily: 'Syne', fontSize: '1.8rem', fontWeight: 800, margin: '0 0 6px' }}>
              Bonjour, {nom} 👋
            </h1>
            <p style={{ color: 'var(--text2)', margin: 0, fontSize: '.9rem' }}>
              {niveau ? `Niveau : ${niveau} · ` : ''}Bienvenue sur votre tableau de bord
            </p>
          </div>
          <button onClick={() => navigate('/profs')} style={{ padding: '11px 22px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 12, cursor: 'pointer', fontWeight: 700, color: '#fff', fontSize: '.9rem', boxShadow: '0 4px 14px rgba(108,99,255,0.35)', display: 'flex', alignItems: 'center', gap: 8 }}>
            🔍 Trouver un professeur
          </button>
        </div>
      </div>

      {/* ── STAT CARDS ── */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 16, marginBottom: 28 }}>
        {[
          { icon: '📚', val: confirmes.length,  lbl: 'Cours confirmés',   color: '#43e97b', bg: 'rgba(67,233,123,0.1)',  onClick: () => navigate('/reservations') },
          { icon: '⏳', val: enAttente.length,  lbl: 'En attente',        color: '#f59e0b', bg: 'rgba(245,158,11,0.1)',  onClick: () => navigate('/reservations') },
          { icon: '✅', val: passes,            lbl: 'Cours passés',      color: '#6c63ff', bg: 'rgba(108,99,255,0.1)',  onClick: () => navigate('/reservations') },
          { icon: '📅', val: prochains.length,  lbl: 'Cours à venir',     color: '#38bdf8', bg: 'rgba(56,189,248,0.1)',  onClick: () => navigate('/reservations') },
        ].map(s => (
          <div key={s.lbl} onClick={s.onClick}
            style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 18, padding: '18px 20px', cursor: 'pointer', transition: 'all .2s' }}
            onMouseEnter={e => { e.currentTarget.style.borderColor=s.color; e.currentTarget.style.transform='translateY(-2px)'; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor='var(--border)'; e.currentTarget.style.transform='none'; }}
          >
            <div style={{ width: 40, height: 40, borderRadius: 11, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', marginBottom: 12 }}>{s.icon}</div>
            <div style={{ fontFamily: 'Syne', fontSize: '2rem', fontWeight: 800, color: s.color, lineHeight: 1 }}>{s.val}</div>
            <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginTop: 4 }}>{s.lbl}</div>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 360px', gap: 24 }}>

        {/* ── COLONNE GAUCHE ── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>

          {/* Prochaines sessions */}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 18 }}>
              <h3 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1rem', fontWeight: 800 }}>📅 Prochains cours</h3>
              <button onClick={() => navigate('/reservations')} style={{ fontSize: '.75rem', color: '#6c63ff', background: 'rgba(108,99,255,0.1)', border: 'none', padding: '4px 12px', borderRadius: 20, cursor: 'pointer', fontWeight: 600 }}>Voir tout →</button>
            </div>
            {prochains.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '32px 20px', color: 'var(--text2)' }}>
                <div style={{ fontSize: '2rem', marginBottom: 10 }}>📭</div>
                <div style={{ fontWeight: 600, marginBottom: 6 }}>Aucun cours à venir</div>
                <button onClick={() => navigate('/profs')} style={{ marginTop: 8, padding: '9px 20px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', border: 'none', borderRadius: 10, cursor: 'pointer', fontWeight: 700, color: '#fff', fontSize: '.85rem' }}>
                  Réserver mon premier cours
                </button>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {prochains.slice(0, 4).map(r => <SessionCard key={r.id} r={r} />)}
              </div>
            )}
          </div>

          {/* Professeurs recommandés */}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 18 }}>
              <h3 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1rem', fontWeight: 800 }}>⭐ Professeurs recommandés</h3>
              <button onClick={() => navigate('/profs')} style={{ fontSize: '.75rem', color: '#6c63ff', background: 'rgba(108,99,255,0.1)', border: 'none', padding: '4px 12px', borderRadius: 20, cursor: 'pointer', fontWeight: 600 }}>Voir tous →</button>
            </div>
            {recommandes.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '20px', color: 'var(--text2)', fontSize: '.85rem' }}>Aucun professeur disponible</div>
            ) : (
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                {recommandes.map(p => {
                  const nom = `${p.user_prenom || ''} ${p.user_nom || ''}`.trim();
                  const mats = p.tarifs_matieres ? [...new Set(p.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 2) : [];
                  return (
                    <div key={p.id} onClick={() => navigate('/profs')}
                      style={{ padding: '14px', background: 'var(--surface2)', borderRadius: 14, cursor: 'pointer', border: '1px solid var(--border)', transition: 'all .2s' }}
                      onMouseEnter={e => { e.currentTarget.style.borderColor='rgba(108,99,255,0.4)'; e.currentTarget.style.background='rgba(108,99,255,0.05)'; }}
                      onMouseLeave={e => { e.currentTarget.style.borderColor='var(--border)'; e.currentTarget.style.background='var(--surface2)'; }}
                    >
                      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
                        <div style={{ width: 38, height: 38, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '.9rem', overflow: 'hidden', flexShrink: 0 }}>
                          {p.photo_url ? <img src={`http://localhost:8001${p.photo_url}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🏫'}
                        </div>
                        <div style={{ minWidth: 0 }}>
                          <div style={{ fontWeight: 700, fontSize: '.82rem', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{nom}</div>
                          <Stars n={p.note_moyenne} />
                        </div>
                      </div>
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
                        {mats.map(m => <span key={m} style={{ fontSize: '.65rem', padding: '2px 7px', borderRadius: 20, background: 'rgba(108,99,255,0.1)', color: '#6c63ff', fontWeight: 600 }}>{m}</span>)}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* ── COLONNE DROITE ── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>

          {/* Profil rapide */}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 22, display: 'flex', flexDirection: 'column', gap: 12 }}>
            <h3 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1rem', fontWeight: 800 }}>👤 Mon profil</h3>
            <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
              <div style={{ width: 52, height: 52, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.4rem', overflow: 'hidden', flexShrink: 0 }}>
                {profil?.photo_url ? <img src={`http://localhost:8001${profil.photo_url}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🎓'}
              </div>
              <div>
                <div style={{ fontWeight: 700, fontSize: '.95rem' }}>{profil?.prenom} {profil?.nom}</div>
                <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>{profil?.email}</div>
              </div>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 7 }}>
              {[
                ['🎓', 'Niveau', niveau || 'Non renseigné'],
                ['📍', 'Ville', profil?.ville || 'Non renseignée'],
                ['📞', 'Téléphone', profil?.telephone || 'Non renseigné'],
              ].map(([icon, label, val]) => (
                <div key={label} style={{ display: 'flex', justifyContent: 'space-between', fontSize: '.8rem', padding: '6px 0', borderBottom: '1px solid var(--border)' }}>
                  <span style={{ color: 'var(--text2)' }}>{icon} {label}</span>
                  <span style={{ fontWeight: 600, color: val.includes('Non') ? 'var(--text2)' : 'var(--text)' }}>{val}</span>
                </div>
              ))}
            </div>
            <button onClick={() => navigate('/profil')} style={{ padding: '9px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, cursor: 'pointer', fontWeight: 600, fontSize: '.82rem', color: 'var(--text)', transition: 'all .15s' }}
              onMouseEnter={e => { e.currentTarget.style.borderColor='#6c63ff'; e.currentTarget.style.color='#6c63ff'; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor='var(--border)'; e.currentTarget.style.color='var(--text)'; }}
            >
              ✏️ Modifier mon profil
            </button>
          </div>

          {/* Actions rapides */}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 22 }}>
            <h3 style={{ fontFamily: 'Syne', margin: '0 0 14px', fontSize: '1rem', fontWeight: 800 }}>⚡ Actions rapides</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {[
                { icon: '👨‍🏫', label: 'Trouver un professeur', path: '/profs',        color: '#6c63ff', bg: 'rgba(108,99,255,0.08)' },
                { icon: '📋', label: 'Mes réservations',      path: '/reservations', color: '#43e97b', bg: 'rgba(67,233,123,0.08)' },
                { icon: '🤖', label: 'Assistant IA',           path: '/chatbot',      color: '#38bdf8', bg: 'rgba(56,189,248,0.08)', badge: 'NEW' },
                { icon: '👤', label: 'Mon profil',             path: '/profil',       color: '#f59e0b', bg: 'rgba(245,158,11,0.08)' },
              ].map(a => (
                <button key={a.path} onClick={() => navigate(a.path)}
                  style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '11px 14px', background: a.bg, border: `1px solid ${a.color}33`, borderRadius: 12, cursor: 'pointer', color: a.color, fontWeight: 600, fontSize: '.85rem', transition: 'all .15s', textAlign: 'left' }}
                  onMouseEnter={e => e.currentTarget.style.transform='translateX(4px)'}
                  onMouseLeave={e => e.currentTarget.style.transform='none'}
                >
                  <span style={{ fontSize: '1rem' }}>{a.icon}</span>
                  <span style={{ flex: 1 }}>{a.label}</span>
                  {a.badge && <span style={{ fontSize: '.6rem', fontWeight: 800, padding: '2px 6px', borderRadius: 20, background: a.color, color: '#fff' }}>{a.badge}</span>}
                  <span style={{ opacity: .6 }}>→</span>
                </button>
              ))}
            </div>
          </div>

          {/* Rappel profil incomplet */}
          {(!niveau || !profil?.ville || !profil?.telephone) && (
            <div style={{ background: 'rgba(245,158,11,0.08)', border: '1px solid rgba(245,158,11,0.25)', borderRadius: 16, padding: 18 }}>
              <div style={{ fontWeight: 700, color: '#f59e0b', marginBottom: 6, fontSize: '.88rem' }}>⚠️ Profil incomplet</div>
              <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginBottom: 12, lineHeight: 1.5 }}>
                Complétez votre profil pour que les professeurs vous connaissent mieux et vous proposent des cours adaptés.
              </div>
              <button onClick={() => navigate('/profil')} style={{ width: '100%', padding: '8px', background: 'rgba(245,158,11,0.15)', border: '1px solid rgba(245,158,11,0.3)', borderRadius: 9, cursor: 'pointer', fontWeight: 700, color: '#f59e0b', fontSize: '.82rem' }}>
                Compléter mon profil →
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
